/**
 * Every third-party asset the game ships, with its licence and source. This list is the single source of truth
 * for docs/ASSETS.md (generated by `npm run assets:build`). Only add assets whose licence page you have read.
 * Downloads are pinned by sha256 in sources.lock.json (written on first fetch, verified afterwards).
 */
export type Licence = 'CC0-1.0' | 'CC-BY-4.0';

export interface SourceFile {
  /** local file name inside .cache/<asset id>/ */
  name: string;
  url: string;
}

export interface AssetSource {
  id: string;
  kind: 'vehicle' | 'texture' | 'hdri' | 'prop';
  title: string;
  /** who made it (as credited by the source) */
  authors: string;
  licence: Licence;
  licenceUrl: string;
  page: string;
  files: SourceFile[];
  /** what we change before shipping */
  modifications: string;
  /** where it is used in the game */
  usage: string;
}

const ph = 'https://dl.polyhaven.org/file/ph-assets';
const phTex = (id: string, maps: [string, string][]): SourceFile[] =>
  maps.map(([map, ext]) => ({ name: `${id}_${map}_1k.${ext}`, url: `${ph}/Textures/${ext}/1k/${id}/${id}_${map}_1k.${ext}` }));
const phModel = (id: string, textures: string[]): SourceFile[] => [
  { name: `${id}_1k.gltf`, url: `${ph}/Models/gltf/1k/${id}/${id}_1k.gltf` },
  { name: `${id}.bin`, url: `${ph}/Models/gltf/1k/${id}/${id}.bin` },
  ...textures.map((t) => ({ name: `textures/${t}`, url: `${ph}/Models/jpg/1k/${id}/${t}` })),
];
const CC0 = { licence: 'CC0-1.0' as const, licenceUrl: 'https://creativecommons.org/publicdomain/zero/1.0/' };

